import govsim.engine.*;import govsim.model.*;import java.util.*;import java.io.*;
public class CalibrarEstadista{public static void main(String[]args)throws Exception{java.lang.reflect.Method m=Simulador.class.getDeclaredMethod("escolher",Estado.class,int.class,Random.class);m.setAccessible(true);PrintWriter out=new PrintWriter(new OutputStreamWriter(new FileOutputStream(args[0]),"UTF-8"));for(Dificuldade d:Dificuldade.values())for(int s:new int[]{0,5}){MotorEconomico motor=new MotorEconomico(new Random(20261103));Random r=new Random(781);Estado e=new Estado();for(int i=0;i<20000;i++){motor.iniciarPartida(e,false,0,d);while(!e.isPartidaEncerrada())motor.processarDecisao(e,(String)m.invoke(null,e,s,r));if(e.isVitoria())out.printf(Locale.US,"%s,%d,%.1f,%.1f,%.1f,%.1f%n",d.name(),s,e.getCaixaPublico().getValorAtual(),e.getAprovacaoPopular().getValorAtual(),e.getPib().getValorAtual(),e.getInflacao().getValorAtual());}}out.close();}}
